// --- watchdog ---------------------------------------------------------------

bool Esp32Watchdog::begin(uint8_t seconds) {
  // A RECONFIGURATION, not an initialisation: the Arduino core has already
  // initialised the TWDT at its own CONFIG_ESP_TASK_WDT_TIMEOUT_S before
  // setup() runs. IDF 4.4 documents that calling it again "will update the
  // TWDT's timeout period and panic configurations instead" and returns ESP_OK,
  // so the value GateConfig.h asserts against is the one in force — but it is
  // CHECKED rather than assumed, because the last thing assumed about this
  // watchdog was its period and the effective value was the core's five
  // seconds.
  //
  // RETRIED rather than asked once. The TWDT is shared state the core set up on
  // another task's schedule, and one refusal is not evidence it will refuse
  // again — while a board that quietly accepted a single refusal runs a whole
  // season under five seconds with every sentence about twelve still written
  // down. Three attempts, with a yield between them, then the lamp says so.
  for (uint8_t attempt = 0U; attempt < kMaxArmAttempts; ++attempt) {
    if (attempt != 0U) {
      delay(10);
    }
#if defined(ESP_ARDUINO_VERSION_MAJOR) && ESP_ARDUINO_VERSION_MAJOR >= 3
    // Arduino-ESP32 3.x (IDF 5): the (seconds, panic) overload is gone, and
    // `esp_task_wdt_init` on an already-initialised TWDT is ESP_ERR_INVALID_STATE
    // rather than the 4.4 "update it". `reconfigure` is the update; `init` is the
    // fallback for a core built without CONFIG_ESP_TASK_WDT_INIT. The idle-task
    // mask keeps both cores' idle tasks watched, as the 2.x default did.
    esp_task_wdt_config_t wdtConfig = {};
    wdtConfig.timeout_ms = static_cast<uint32_t>(seconds) * 1000U;
    wdtConfig.idle_core_mask = (1U << portNUM_PROCESSORS) - 1U;
    wdtConfig.trigger_panic = true;
    esp_err_t configured = esp_task_wdt_reconfigure(&wdtConfig);
    if (configured == ESP_ERR_INVALID_STATE) {
      configured = esp_task_wdt_init(&wdtConfig);
    }
#else
    const esp_err_t configured = esp_task_wdt_init(static_cast<uint32_t>(seconds), true);
#endif
    esp_err_t subscribed = esp_task_wdt_add(nullptr);
    // DG-7: ALREADY SUBSCRIBED IS SUBSCRIBED. A retry after a first attempt
    // whose init failed but whose add took gets ESP_ERR_INVALID_ARG for ever,
    // and 1.x reported "not armed" for a loop that was in fact watched.
    if (subscribed == ESP_ERR_INVALID_ARG) {
      subscribed = ESP_OK;
    }
    if (subscribed != ESP_OK) {
      // And a failed subscription falls back to the loop task BY HANDLE: on this
      // core the loop task is not watched by default (loopTaskWDTEnabled is
      // false), so a board that could not subscribe would otherwise run with
      // no watchdog over the lock at all.
      subscribed = esp_task_wdt_add(xTaskGetCurrentTaskHandle());
      if (subscribed == ESP_ERR_INVALID_ARG) {
        subscribed = ESP_OK;
      }
    }
    if (configured == ESP_OK && subscribed == ESP_OK) {
      return true;
    }
  }
  return false;
}

void Esp32Watchdog::kick() {
  esp_task_wdt_reset();
}

