WebServer gPortalServer(80);
bool gSubmitted = false;
char gReason[32] = {};
bool gAccepted = false;

char gSsid[devnet::kSsidMax + 1U];
char gPsk[devnet::kPskMax + 1U];
char gSsid2[devnet::kSsidMax + 1U];
